#include <stdio.h>
#include <stdlib.h>

#define MAXN 305
#define MAXS 2705
#define INF 1000000000

int dp[MAXN][MAXS];

int main() {
    int N, K, T;
    scanf("%d %d %d", &N, &K, &T);
    int P[305];
    for (int i = 0; i < N; i++) scanf("%d", &P[i]);
    int G[305];
    int a[305];
    int cnt = 0;
    for (int i = 0; i < N; i++) {
        scanf("%d", &G[i]);
        if (G[i] == 1) {
            a[cnt++] = i;
        }
    }
    int S = 9 * K;
    for (int i = 0; i <= K; i++)
        for (int j = 0; j <= S; j++)
            dp[i][j] = INF;
    dp[0][0] = 0;
    for (int i = 0; i < N; i++) {
        int v = P[i];
        int maxj = (i < K - 1) ? i : K - 1;
        for (int j = maxj; j >= 0; j--) {
            int cost_add = abs(a[j] - i);
            int maxs = 9 * j;
            for (int s = 0; s <= maxs; s++) {
                if (dp[j][s] != INF) {
                    int new_s = s + v;
                    int new_cost = dp[j][s] + cost_add;
                    if (new_cost < dp[j + 1][new_s]) {
                        dp[j + 1][new_s] = new_cost;
                    }
                }
            }
        }
    }
    for (int s = S; s >= 0; s--) {
        if (dp[K][s] <= T) {
            printf("%d\n", s);
            break;
        }
    }
    return 0;
}
